import pandas as pd

def clean(df):
    df = df.copy()
    # Process flipper_length_mm
    df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
    df = df[(df['flipper_length_mm'] >= 170) & (df['flipper_length_mm'] <= 235) & ~pd.isna(df['flipper_length_mm'])]
    # Process species
    correction = {
        'adelie': 'Adelie',
        'chinstrap': 'Chinstrap',
        'gentoo': 'Gentoo',
        'Gentto': 'Gentoo',
    }
    df['species'] = df['species'].map(correction)
    allowed_species = {'Adelie', 'Chinstrap', 'Gentoo'}
    df = df[df['species'].isin(allowed_species)]
    return df

def answer(df):
    grouped = df.groupby('species')['flipper_length_mm'].mean().reset_index()
    return {name: value for name, value in grouped.iterrows()}
